    @Test
    public void ReplacementValuesTest() {
        DefaultExtremeValuesCorrector deEVC = new DefaultExtremeValuesCorrector();
        DoubleSeq s = DoubleSeq.of(ABS);
        double[] one = new double[s.length()];
        int period = 12;
        Arrays.fill(one, 1.0);
        deEVC.setSweights(DoubleSeq.of(one));
        DoubleSeq sqSeriesEVR = deEVC.computeCVCorrections(s, period);
        Assert.assertArrayEquals(resultCV, sqSeriesEVR.toArray(), 0.000005);
    }

    @Test
    public void FilterSelectionCVtest() {
        DoubleSeq sqABS = DoubleSeq.of(ABS);
        TsData tsABS = TsData.of(TsPeriod.monthly(1990, 1), sqABS);
        X11Context x11Context = X11Context.of(X11Spec.DEFAULT, tsABS);
        CrossValidation cv= new CrossValidation();
        cv.calculatedSF_CrossValidation(sqABS, x11Context);
        
   Assert.assertEquals("Filters are wrong","S3X3", cv.getSeasonalFilterOptionCV().toString());
   
    }

    
        
